// src/services/driveApi.js
// Updated Google Drive API service with better error handling

const API_KEY = process.env.REACT_APP_GOOGLE_API_KEY;
const DISCOVERY_DOC = 'https://www.googleapis.com/discovery/v1/apis/drive/v3/rest';

// Check if API key is configured
const checkApiKey = () => {
  if (!API_KEY) {
    console.error('Google Drive API key not configured. Please set REACT_APP_GOOGLE_API_KEY in your .env file');
    throw new Error('Google Drive API key not configured. Please set REACT_APP_GOOGLE_API_KEY in your environment variables.');
  }
  return true;
};

// Initialize Google Drive API
export const initializeDriveApi = async () => {
  try {
    checkApiKey();
    
    if (typeof window.gapi === 'undefined') {
      // Load Google API script if not already loaded
      await loadGoogleApiScript();
    }
    
    await window.gapi.load('client', async () => {
      await window.gapi.client.init({
        apiKey: API_KEY,
        discoveryDocs: [DISCOVERY_DOC],
      });
    });
    
    console.log('Google Drive API initialized successfully');
    return true;
  } catch (error) {
    console.error('Failed to initialize Google Drive API:', error);
    throw error;
  }
};

// Load Google API script dynamically
const loadGoogleApiScript = () => {
  return new Promise((resolve, reject) => {
    if (document.querySelector('script[src="https://apis.google.com/js/api.js"]')) {
      resolve();
      return;
    }
    
    const script = document.createElement('script');
    script.src = 'https://apis.google.com/js/api.js';
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
};

// Fetch images from Google Drive folder
export const fetchDriveImages = async (folderId) => {
  try {
    checkApiKey();
    
    if (!folderId) {
      throw new Error('Folder ID is required');
    }
    
    // Initialize API if not already done
    if (typeof window.gapi === 'undefined' || !window.gapi.client) {
      await initializeDriveApi();
    }
    
    console.log(`Fetching images from folder: ${folderId}`);
    
    const response = await window.gapi.client.drive.files.list({
      q: `'${folderId}' in parents and mimeType contains 'image/' and trashed=false`,
      fields: 'files(id,name,mimeType,webViewLink,thumbnailLink)',
      orderBy: 'name'
    });
    
    if (!response.result || !response.result.files) {
      console.warn('No files returned from Google Drive API');
      return [];
    }
    
    const files = response.result.files;
    console.log(`Found ${files.length} images in folder ${folderId}`);
    
    return files;
    
  } catch (error) {
    console.error('Error fetching Drive images:', error);
    
    // Provide more specific error messages
    if (error.message.includes('API key not configured')) {
      throw new Error('Google Drive API key not configured. Please check your environment variables.');
    } else if (error.status === 403) {
      throw new Error('Access denied to Google Drive folder. Please check folder permissions and API key.');
    } else if (error.status === 404) {
      throw new Error('Google Drive folder not found. Please check the folder ID.');
    } else {
      throw new Error(`Failed to load images from Google Drive: ${error.message}`);
    }
  }
};

// Alternative method: Fetch images using direct HTTP request (fallback)
export const fetchDriveImagesDirect = async (folderId) => {
  try {
    checkApiKey();
    
    if (!folderId) {
      throw new Error('Folder ID is required');
    }
    
    const url = `https://www.googleapis.com/drive/v3/files?q='${folderId}'+in+parents+and+mimeType+contains+'image/'+and+trashed=false&fields=files(id,name,mimeType)&key=${API_KEY}`;
    
    const response = await fetch(url);
    
    if (!response.ok) {
      if (response.status === 403) {
        throw new Error('Access denied to Google Drive folder. Please check folder permissions and API key.');
      } else if (response.status === 404) {
        throw new Error('Google Drive folder not found. Please check the folder ID.');
      } else {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
    }
    
    const data = await response.json();
    
    if (data.error) {
      throw new Error(`Google Drive API error: ${data.error.message}`);
    }
    
    console.log(`Found ${data.files?.length || 0} images using direct API call`);
    return data.files || [];
    
  } catch (error) {
    console.error('Error with direct Drive API call:', error);
    throw error;
  }
};

// Utility function to get direct image URL
export const getDriveImageUrl = (fileId) => {
  return `https://drive.google.com/uc?export=view&id=${fileId}`;
};

// Utility function to get thumbnail URL
export const getDriveThumbnailUrl = (fileId, size = 400) => {
  return `https://drive.google.com/thumbnail?id=${fileId}&sz=w${size}`;
};

// Test function to verify API setup
export const testDriveApiSetup = async () => {
  try {
    checkApiKey();
    console.log('✅ Google Drive API key is configured');
    
    // Try to initialize the API
    await initializeDriveApi();
    console.log('✅ Google Drive API initialized successfully');
    
    return true;
  } catch (error) {
    console.error('❌ Google Drive API setup test failed:', error.message);
    return false;
  }
};