// src/components/BrandGallery.jsx
// Updated with better error handling and fallback options

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { fetchDriveImages, fetchDriveImagesDirect, testDriveApiSetup } from '../services/driveApi.js';
import './BrandGallery.css';

export default function BrandGallery({ folderId, fallbackImages = [] }) {
  const [imageUrls, setImageUrls] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedImage, setSelectedImage] = useState(null);
  const [apiSetupTested, setApiSetupTested] = useState(false);

  useEffect(() => {
    if (!folderId) {
      setError('No folder ID provided');
      return;
    }

    loadImages();
  }, [folderId]);

  const loadImages = async () => {
    setLoading(true);
    setError(null);

    try {
      // Test API setup first
      if (!apiSetupTested) {
        const setupOk = await testDriveApiSetup();
        setApiSetupTested(true);
        
        if (!setupOk) {
          throw new Error('Google Drive API not properly configured');
        }
      }

      // Try primary method first
      let files;
      try {
        files = await fetchDriveImages(folderId);
      } catch (primaryError) {
        console.warn('Primary API method failed, trying direct method:', primaryError.message);
        // Fallback to direct API call
        files = await fetchDriveImagesDirect(folderId);
      }

      if (!files || !Array.isArray(files)) {
        throw new Error('Invalid response from Drive API');
      }

      // Filter for images and build URLs
      const imageFiles = files.filter(f => 
        f.mimeType && f.mimeType.startsWith('image/')
      );

      if (imageFiles.length === 0) {
        if (fallbackImages.length > 0) {
          console.log('No Drive images found, using fallback images');
          setImageUrls(fallbackImages.map((img, index) => ({
            id: `fallback-${index}`,
            url: img.url || img,
            name: img.name || `Image ${index + 1}`,
            mimeType: 'image/jpeg'
          })));
        } else {
          setError('No images found in this folder');
          setImageUrls([]);
        }
        return;
      }

      const urls = imageFiles.map(f => ({
        id: f.id,
        url: `https://drive.google.com/uc?export=view&id=${f.id}`,
        name: f.name || 'Untitled',
        mimeType: f.mimeType,
        thumbnail: `https://drive.google.com/thumbnail?id=${f.id}&sz=w400`
      }));

      setImageUrls(urls);
      console.log(`Successfully loaded ${urls.length} images from Google Drive`);

    } catch (err) {
      console.error('Error loading Drive images:', err);
      
      // Use fallback images if available
      if (fallbackImages.length > 0) {
        console.log('Using fallback images due to Drive API error');
        setImageUrls(fallbackImages.map((img, index) => ({
          id: `fallback-${index}`,
          url: img.url || img,
          name: img.name || `Image ${index + 1}`,
          mimeType: 'image/jpeg'
        })));
        setError(`Drive API unavailable, showing ${fallbackImages.length} fallback images`);
      } else {
        setError(getErrorMessage(err));
        setImageUrls([]);
      }
    } finally {
      setLoading(false);
    }
  };

  const getErrorMessage = (error) => {
    if (error.message.includes('API key not configured')) {
      return 'Google Drive API not configured. Please set up your API key in environment variables.';
    } else if (error.message.includes('Access denied')) {
      return 'Access denied to Google Drive folder. Please check folder permissions.';
    } else if (error.message.includes('not found')) {
      return 'Google Drive folder not found. Please check the folder ID.';
    } else {
      return error.message || 'Failed to load images from Google Drive';
    }
  };

  const handleImageError = (imageId) => {
    console.warn(`Failed to load image with ID: ${imageId}`);
    // Remove the failed image from the list
    setImageUrls(prev => prev.filter(img => img.id !== imageId));
  };

  const openLightbox = (image) => {
    setSelectedImage(image);
  };

  const closeLightbox = () => {
    setSelectedImage(null);
  };

  const retryLoad = () => {
    setApiSetupTested(false); // Reset API test
    loadImages();
  };

  // Loading state
  if (loading) {
    return (
      <div className="brand-gallery-container">
        <div className="flex items-center justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white"></div>
          <span className="ml-3 text-white">Loading gallery...</span>
        </div>
      </div>
    );
  }

  // Error state
  if (error && imageUrls.length === 0) {
    return (
      <div className="brand-gallery-container">
        <div className="bg-red-900/20 border border-red-500/30 rounded-lg p-6 text-center">
          <div className="text-red-400 mb-2">⚠️ Gallery Error</div>
          <p className="text-gray-300 text-sm mb-4">{error}</p>
          <div className="flex gap-3 justify-center">
            <button 
              onClick={retryLoad} 
              className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded text-sm transition-colors"
            >
              Retry
            </button>
            <button 
              onClick={() => window.open('https://console.cloud.google.com/', '_blank')} 
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm transition-colors"
            >
              Setup API Key
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Empty state
  if (imageUrls.length === 0) {
    return (
      <div className="brand-gallery-container">
        <div className="bg-gray-800/30 border border-gray-600/30 rounded-lg p-6 text-center">
          <div className="text-gray-400 mb-2">📷 No Images</div>
          <p className="text-gray-500 text-sm">No images found in this gallery</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="brand-gallery-container">
        {/* Show warning if using fallback images */}
        {error && imageUrls.length > 0 && (
          <div className="bg-yellow-900/20 border border-yellow-500/30 rounded-lg p-3 mb-4 text-center">
            <div className="text-yellow-400 text-sm">⚠️ {error}</div>
          </div>
        )}
        
        <div className="brand-gallery">
          {imageUrls.map((image, index) => (
            <motion.div
              key={image.id}
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
              className="gallery-item"
              onClick={() => openLightbox(image)}
            >
              <img 
                src={image.thumbnail || image.url} 
                className="gallery-img" 
                alt={image.name}
                loading="lazy"
                onError={() => handleImageError(image.id)}
                onLoad={(e) => {
                  // Fade in the image once it's loaded
                  e.target.style.opacity = '1';
                }}
                style={{ opacity: '0', transition: 'opacity 0.3s ease' }}
              />
              <div className="gallery-overlay">
                <span className="gallery-overlay-text">View</span>
              </div>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Lightbox Modal */}
      <AnimatePresence>
        {selectedImage && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="lightbox-overlay"
            onClick={closeLightbox}
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              className="lightbox-content"
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                className="lightbox-close"
                onClick={closeLightbox}
              >
                ✕
              </button>
              <img 
                src={selectedImage.url} 
                alt={selectedImage.name}
                className="lightbox-image"
              />
              <div className="lightbox-caption">
                {selectedImage.name}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}